ame="remove_photo" id="removePhoto"><label class="form-check-label" for="removePhoto">Remove current photo</label></div><?php endif;?></div><div class="col-md-9"><div class="row g-3"><div class="col-md-4"><label class="form-label">BDC ID</label><input class="form-control" value="<?=e($c['bdc_id']?:'Generated after save')?>" disabled></div><div class="col-md-8"><label class="form-label">Exact name</label><input class="form-control" name="exact_name" value="<?=e($c['exact_name'])?>" required></div><div class="col-md-4"><label class="form-label">Country</label><input class="form-control" name="country" value="<?=e((string)$c['country'])?>"></div><div class="col-md-4"><label class="form-label">Role</label><select class="form-select" name="dance_role"><?php foreach(['unknown','leader','follower','both'] as $v):?><option value="<?=$v?>" <?=$c['dance_role']===$v?'selected':''?>><?=e(ucfirst($v))?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Current division</label><select class="form-select" name="current_division"><?php foreach(['unknown','novice','intermediate','advanced','all_star','professional'] as $v):?><option value="<?=$v?>" <?=$c['current_division']===$v?'selected':''?>><?=e(ucwords(str_replace('_',' ',$v)))?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Instagram</label><input class="form-control" name="instagram" value="<?=e((string)$c['instagram'])?>"></div><div class="col-md-4"><label class="form-label">Email, private</label><input class="form-control" type="email" name="email" value="<?=e((string)$c['email'])?>"></div><div class="col-md-4"><label class="form-label">Phone, private</label><input class="form-control" name="phone" value="<?=e((string)$c['phone'])?>"></div><div class="col-md-4"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['active','pending','archived'] as $v):?><option <?=$c['status']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-md-8 d-flex align-items-end"><div class="form-check mb-2"><input class="form-check-input" type="checkbox" name="show_on_leaderboard" id="show" <?=$c['show_on_leaderboard']?'checked':''?>><label class="form-check-label" for="show">Show on public leaderboard</label></div></div><div class="col-12"><div class="card border-warning-subtle bg-warning-subtle"><div class="card-body"><h2 class="h6 mb-3">Manual division eligibility</h2><p class="small text-muted mb-3">Use these only when BDC has ruled that a competitor is out of a division and the automatic points or competition history does not detect it.</p><div class="row g-3"><div class="col-md-4"><div class="form-check"><input class="form-check-input" type="checkbox" name="novice_manual_out" id="noviceManualOut" <?=!empty($c['novice_manual_out'])?'checked':''?>><label class="form-check-label fw-semibold" for="noviceManualOut">Manually mark out of Novice</label></div></div><div class="col-md-4"><div class="form-check"><input class="form-check-input" type="checkbox" name="intermediate_manual_out" id="intermediateManualOut" <?=!empty($c['intermediate_manual_out'])?'checked':''?>><label class="form-check-label fw-semibold" for="intermediateManualOut">Manually mark out of Intermediate</label></div></div><div class="col-md-4"><label class="form-label">Reason</label><input class="form-control" name="division_override_reason" value="<?=e((string)$c['division_override_reason'])?>" placeholder="Committee ruling or historical record"></div></div></div></div></div><div class="col-12"><label class="form-label">Internal admin notes</label><textarea class="form-control" rows="3" name="admin_notes"><?=e((string)$c['admin_notes'])?></textarea></div></div></div></div></div><div class="card-footer bg-white p-3 d-flex gap-2"><button class="btn btn-dark">Save competitor</button><a class="btn btn-outline-secondary" href="./">Back</a></div></form>
